/*
 * Modified by Actuna Sp. z o.o.:
 *   new module (#45): hides the credentials of URLs in text (errors, logs, API)
 *   #63: urlCredentialSecrets - the literal secrets of one URL (the install URL of a module)
 * This notice is required by section 4(b) of the Apache License 2.0.
 */

/**
 * Hiding of the credentials of URLs in text (#45).
 *
 * Internal to the runtime: it is exported by `@node-red/util` but NOT by
 * `util.util`, so it is not part of `RED.util` seen by nodes.
 *
 * @ignore
 */

// Scheme, "://", then the user info up to the last "@" before the first "/" or
// white space. The scheme is bounded and every class is a single negated set,
// so the matching is linear (no nested or overlapping quantifiers).
const URL_USERINFO_RE = /([A-Za-z][A-Za-z0-9+.-]{0,15}):\/\/([^\s/]+)@/g;
const SSH_SCHEMES = ["ssh", "git+ssh"];

/**
 * Hides the credentials of every URL in a text: `scheme://user:pass@host` and
 * `scheme://token@host` become `scheme://***@host`. For `ssh` URLs only a user
 * info with a password (`ssh://user:pass@host`) is hidden - the bare user of
 * `ssh://git@host` is not a secret. Text without credentials, including the
 * scp-like form `git@host:org/repo`, is returned unchanged. A value that is not
 * a string is returned as it is.
 *
 * The regular expression cannot recognise a password with an unescaped `/` or
 * white space, so the caller can pass `secrets` - literal strings (known user
 * infos and passwords) that are replaced by `***` wherever they occur, longest first.
 *
 * @param  {any} text - the text (error message, log line, URL)
 * @param  {String[]} [secrets] - literal secrets to hide as well
 * @return {any} the text with the credentials replaced by `***`
 */
function maskUrlCredentials(text, secrets) {
    if (typeof text !== "string") {
        return text;
    }
    let result = text;
    if (Array.isArray(secrets) && secrets.length > 0) {
        secrets.filter(s => typeof s === "string" && s.length > 0)
            .sort((a, b) => b.length - a.length)
            .forEach(s => { result = result.split(s).join("***"); });
    }
    return result.replace(URL_USERINFO_RE, function(match, scheme, userinfo) {
        if (SSH_SCHEMES.includes(scheme.toLowerCase()) && userinfo.indexOf(":") === -1) {
            return match;
        }
        return scheme + "://***@";
    });
}

// A literal secret shorter than this is not hidden as a literal (the same rule as the
// secrets of the remotes of a project): a short text would hide too much of a log line.
const MIN_SECRET_LENGTH = 4;
const URL_SCHEME_RE = /^[A-Za-z][A-Za-z0-9+.-]*:\/\//;

// The user info of a URL, or null: the text between "scheme://" and the last "@" of the
// authority (up to the first "/"). When the authority has no "@" but the URL has one later
// and the authority looks like "user:password" (a password with an unescaped "/"), the
// user info is the text up to the last "@" of the URL. The same rule as the user info of
// the remotes of a project (runtime projects/git).
function getUserinfo(url) {
    const m = URL_SCHEME_RE.exec(url);
    if (!m) {
        return null;
    }
    const rest = url.substring(m[0].length);
    const slash = rest.indexOf("/");
    const authority = slash === -1 ? rest : rest.substring(0, slash);
    const at = authority.lastIndexOf("@");
    if (at !== -1) {
        return rest.substring(0, at);
    }
    const lastAt = rest.lastIndexOf("@");
    // "user:password" before the first "/" (a numeric part after ":" is a port)
    if (lastAt !== -1 && /^[^:@]+:(?!\d+$)/.test(authority)) {
        return rest.substring(0, lastAt);
    }
    return null;
}

function decoded(text) {
    try {
        return decodeURIComponent(text);
    } catch (malformed) {
        // not a valid percent-encoding (URIError): there is no decoded form to hide,
        // the text itself is hidden
        return text;
    }
}

/**
 * The literal secrets of one URL, for `maskUrlCredentials(text, secrets)` and the
 * `secrets` of `exec.run`: its user info, its password (after the first ":") and
 * their URI-decoded forms, each at least 4 characters long. A tool (npm, git) can print
 * them outside the URL form (`user:password`, the decoded password), where the
 * pattern of `maskUrlCredentials` does not find them. The bare user of an `ssh` URL
 * (`ssh://git@host`) is not a secret. A value that is not a URL with a user info gives
 * an empty list.
 *
 * @param  {any} url - the URL (any other value gives no secret)
 * @return {String[]} the secrets, without duplicates
 */
function urlCredentialSecrets(url) {
    if (typeof url !== "string") {
        return [];
    }
    const userinfo = getUserinfo(url);
    if (!userinfo) {
        return [];
    }
    const scheme = url.substring(0, url.indexOf(":")).toLowerCase();
    if (SSH_SCHEMES.includes(scheme) && userinfo.indexOf(":") === -1) {
        return [];
    }
    const candidates = [userinfo];
    const colon = userinfo.indexOf(":");
    if (colon !== -1) {
        candidates.push(userinfo.substring(colon + 1));
    }
    candidates.slice().forEach(function(secret) {
        candidates.push(decoded(secret));
    });
    const secrets = [];
    candidates.forEach(function(secret) {
        if (secret.length >= MIN_SECRET_LENGTH && secrets.indexOf(secret) === -1) {
            secrets.push(secret);
        }
    });
    return secrets;
}

module.exports = {
    maskUrlCredentials: maskUrlCredentials,
    urlCredentialSecrets: urlCredentialSecrets
};
